using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

namespace Desensitizer
{
 public sealed class Mapping { public Dictionary<string,List<CompanyIntroduction>>? CompanyIntroductions {get;set;} public List<string> IdentityFileIds {get;set;}=new List<string>(); public List<EntityOccurrence> Occurrences {get;set;}=new List<EntityOccurrence>(); public string IdentityStatus {get;set;}=""; public bool RequiresContextReview {get;set;} public string ContextReviewAcknowledgement {get;set;}=""; public string ContextReviewEvidenceKey {get;set;}=""; public void AcknowledgeContextReview(){ContextReviewAcknowledgement=ContextReviewEvidenceKey;RequiresContextReview=false;} public string OriginalValue {get;set;}=""; public string NormalizedValue {get;set;}=""; public string Category {get;set;}="PERSON"; public string Token {get;set;}=""; public DateTimeOffset CreatedAt {get;set;}=DateTimeOffset.UtcNow; public bool Approved {get;set;}=true; public bool Ignored {get;set;} public double Confidence {get;set;}=1; public string DetectionSource {get;set;}="Manual"; public List<string> DetectionSources {get;set;}=new List<string>(); public string Explanation {get;set;}=""; public bool IsManual {get;set;} public List<string> SourceFileIds {get;set;}=new List<string>(); public string ConfidenceLabel=>IsManual?"Analyst":HasLocalAi?"Not calibrated":Confidence<=0?"Not calibrated":"Detector score "+Math.Round(Confidence*100)+"%"; public bool NeedsVerification=>!IsManual&&(RequiresContextReview||Confidence<0.95); public string VerificationLabel=>NeedsVerification?"⚠ verify":""; private int DetectionCount=>DetectionSources?.Count??0; private bool HasLocalAi=>DetectionSource=="Local AI"||(DetectionSources?.Contains("Local AI")??false); public string DetectionLabel=>IsManual?"● Analyst-added":HasLocalAi?(DetectionCount>1?"● AI + detectors":"● Local AI"):DetectionCount>1?"● Corroborated":"● Single detector"; public string DetectionHelp=>IsManual?"Added directly by an analyst.":HasLocalAi?"Suggested by the bundled local language model. Its confidence is not calibrated; review the exact text before replacing.":DetectionCount>1?"Matched by "+DetectionCount+" independent local detectors.":"Matched by one local detector. Review its context and confidence."; [System.Text.Json.Serialization.JsonIgnore] public string Decision {get=>Ignored?"Keep as-is":Approved?"Replace":"Review";set{Ignored=value=="Keep as-is";Approved=value=="Replace";}} }
 public sealed class FileRecord { public string Id {get;set;}=Guid.NewGuid().ToString("N"); public string SourcePath {get;set;}=""; public string Display {get;set;}=""; public DateTimeOffset AddedAt {get;set;}=DateTimeOffset.UtcNow; public string Status {get;set;}="Added"; public DateTimeOffset? LastScanAt {get;set;} public DateTimeOffset? LastDeepReviewAt {get;set;} public bool DeepReviewComplete {get;set;} public string DeepReviewWarning {get;set;}=""; /* Content fingerprint of the source file when it was last scanned or deep checked (UI-8). Null in projects saved before this field existed: unknown. */ public string? ContentSha256 {get;set;} public long? ContentLength {get;set;} }
 public sealed class Project { public string Name {get;set;}=""; public bool AutoScanOnAdd {get;set;}=true; /* Per-project review preferences (keep-as-is labels, generic terms). Projects saved before this field existed load with empty preferences. */ private ProjectReviewPreferences _reviewPreferences=new ProjectReviewPreferences(); public ProjectReviewPreferences ReviewPreferences {get=>_reviewPreferences;set=>_reviewPreferences=value??new ProjectReviewPreferences();} /* Set once a passphrase has been accepted: by unlocking the project or by the strength rules. Save enforces the rules for a new project only. */ [System.Text.Json.Serialization.JsonIgnore] public bool PassphraseAccepted {get;set;} [System.Text.Json.Serialization.JsonIgnore] public ProjectFormat LoadedFormat {get;set;} public List<Mapping> Mappings {get;set;}=new List<Mapping>(); public List<FileRecord> Files {get;set;}=new List<FileRecord>(); /* Interrupted document checks that can be resumed, by file id. Stored inside the encrypted project only (UiCheckpoint.cs). */ private Dictionary<string,ReviewCheckpoint> _reviewCheckpoints=new Dictionary<string,ReviewCheckpoint>(); public Dictionary<string,ReviewCheckpoint> ReviewCheckpoints {get=>_reviewCheckpoints;set=>_reviewCheckpoints=value??new Dictionary<string,ReviewCheckpoint>();} [System.Text.Json.Serialization.JsonIgnore] public string Passphrase {get;set;}="";
  public static Project New(string name,string passphrase)=>new Project{Name=name,Passphrase=passphrase};
  public Mapping EnsureMapping(string value,string category,bool approved=false,double confidence=1,string source="Manual",string explanation="",string? sourceFileId=null,bool isManual=false) { var norm=Normalize(value); var found=Mappings.FirstOrDefault(m=>m.NormalizedValue==norm&&m.Category.Equals(category,StringComparison.OrdinalIgnoreCase)&&(category!="PERSON"||isManual||string.IsNullOrEmpty(sourceFileId)||(m.SourceFileIds.Contains(sourceFileId)||(m.IdentityFileIds?.Contains(sourceFileId)??false)))); if(found!=null) { _rescanTouched?.Add(found); if(approved)found.Approved=true; if(isManual)found.IsManual=true; AddSource(found,sourceFileId); AddDetectionSource(found,source); if(confidence>found.Confidence){found.Confidence=confidence;found.DetectionSource=source;found.Explanation=explanation;} return found; } var prefix=category.ToUpperInvariant(); var aliasToken=prefix=="PERSON"?FindPersonAliasToken(value,sourceFileId):FindPunctuationAliasToken(value,prefix); var n=NextTokenNumber(prefix); var item=new Mapping {OriginalValue=value,NormalizedValue=norm,Category=prefix,Token=aliasToken??"["+prefix+"_"+n.ToString("000")+"]",Approved=approved,Confidence=confidence,DetectionSource=source,Explanation=explanation,IsManual=isManual,DetectionSources=new List<string>{source}}; AddSource(item,sourceFileId); Mappings.Add(item); _rescanTouched?.Add(item); return item; }
  public Mapping EnsureMapping(Candidate candidate,string? sourceFileId,bool approved=false){var mapping=EnsureMapping(candidate.Value,candidate.Category,approved,candidate.Confidence,candidate.Source,candidate.Explanation,sourceFileId,false);if(candidate.RequiresContextReview){mapping.ContextReviewEvidenceKey=ContextReviewEvidence.Signature(candidate,sourceFileId);mapping.RequiresContextReview=mapping.ContextReviewAcknowledgement!=mapping.ContextReviewEvidenceKey;}if(mapping.RequiresContextReview&&!mapping.IsManual)mapping.Approved=false;foreach(var source in candidate.DetectionSources??new List<string>())AddDetectionSource(mapping,source);return mapping;}
  public void PrepareFileRescan(string fileId){foreach(var mapping in Mappings.Where(m=>!m.IsManual)){mapping.IdentityFileIds??=new List<string>();if(mapping.SourceFileIds.Contains(fileId)&&!mapping.IdentityFileIds.Contains(fileId))mapping.IdentityFileIds.Add(fileId);mapping.SourceFileIds.RemoveAll(id=>id==fileId);}}
  public void RemoveOrphanedMappings()=>Mappings.RemoveAll(m=>m.SourceFileIds.Count==0);
  /* UI-3: a rescan or deep check keeps the file's mappings and their decisions until the new results exist. Mappings the new results find again are reused as they are (same token, same decision). BeginRescan only remembers which mappings belonged to the file; CommitRescan, called once the new results are complete, detaches the file from the ones that were not found again and drops those left with no file; AbandonRescan (stop, failure, incomplete results) changes nothing. Nothing here is saved. */ private HashSet<Mapping>? _rescanPrior; private HashSet<Mapping>? _rescanTouched;
  public void BeginRescan(string fileId){_rescanPrior=new HashSet<Mapping>(Mappings.Where(m=>!m.IsManual&&m.SourceFileIds.Contains(fileId)));_rescanTouched=new HashSet<Mapping>();foreach(var mapping in _rescanPrior){mapping.IdentityFileIds??=new List<string>();if(!mapping.IdentityFileIds.Contains(fileId))mapping.IdentityFileIds.Add(fileId);}}
  public void CommitRescan(string fileId){if(_rescanPrior!=null&&_rescanTouched!=null)foreach(var mapping in _rescanPrior)if(!_rescanTouched.Contains(mapping))mapping.SourceFileIds.RemoveAll(id=>id==fileId);_rescanPrior=null;_rescanTouched=null;RemoveOrphanedMappings();}
  public void AbandonRescan(){_rescanPrior=null;_rescanTouched=null;}
  public void EnsureFileProvenance(){foreach(var file in Files)if(string.IsNullOrWhiteSpace(file.Id))file.Id=Guid.NewGuid().ToString("N");if(Files.Count==0){Mappings.Clear();return;}foreach(var mapping in Mappings){if(mapping.SourceFileIds==null)mapping.SourceFileIds=new List<string>();if(mapping.SourceFileIds.Count==0)mapping.SourceFileIds.AddRange(Files.Select(f=>f.Id));if(mapping.DetectionSources==null)mapping.DetectionSources=new List<string>();if(mapping.DetectionSources.Count==0&&!string.IsNullOrWhiteSpace(mapping.DetectionSource))mapping.DetectionSources.Add(mapping.DetectionSource);}ConsolidatePersonAliases();}
  public void RemoveFile(FileRecord file){Files.Remove(file);UiResume.RemoveFileCheckpoints(ReviewCheckpoints,file.Id);foreach(var mapping in Mappings){mapping.SourceFileIds.RemoveAll(id=>id==file.Id);mapping.IdentityFileIds?.RemoveAll(id=>id==file.Id);mapping.Occurrences?.RemoveAll(o=>o.FileId==file.Id);mapping.CompanyIntroductions?.Remove(file.Id);}if(Files.Count==0)Mappings.Clear();else RemoveOrphanedMappings();}
  private int NextTokenNumber(string prefix)=>MappingTokenSafety.NextNumber(Mappings,prefix);
  private static void AddSource(Mapping mapping,string? sourceFileId){mapping.IdentityFileIds??=new List<string>();if(!string.IsNullOrWhiteSpace(sourceFileId)&&!mapping.IdentityFileIds.Contains(sourceFileId))mapping.IdentityFileIds.Add(sourceFileId);if(mapping.SourceFileIds==null)mapping.SourceFileIds=new List<string>();if(!string.IsNullOrWhiteSpace(sourceFileId)&&!mapping.SourceFileIds.Contains(sourceFileId))mapping.SourceFileIds.Add(sourceFileId);}
  private static void AddDetectionSource(Mapping mapping,string source){if(mapping.DetectionSources==null)mapping.DetectionSources=new List<string>();if(!string.IsNullOrWhiteSpace(source)&&!mapping.DetectionSources.Contains(source))mapping.DetectionSources.Add(source);}
  private string? FindPunctuationAliasToken(string value,string category)
  {
   if(category is not ("ORGANIZATION" or "VENDOR")||!Regex.IsMatch(value,@"\b(?:Inc|Corporation|Corp|Ltd|Limited|LLC)\.?$",RegexOptions.IgnoreCase))return null;
   var key=Normalize(value.TrimEnd('.'));
   var tokens=Mappings.Where(m=>m.Category==category&&MappingTokenSafety.IsAutomaticAlias(m)&&Normalize(m.OriginalValue.TrimEnd('.'))==key).Select(m=>m.Token).Distinct().ToArray();
   return tokens.Length==1?tokens[0]:null;
  }
  public void ConsolidatePersonAliases() => PersonIdentity.Consolidate(Mappings);
  public void RefreshOccurrenceEvidence(string fileId,string text) => OccurrenceIdentity.Refresh(fileId,text,Mappings);
  private string? FindPersonAliasToken(string value,string? sourceFileId)
  {
   var matches=Mappings.Where(m=>m.Category=="PERSON"&&MappingTokenSafety.IsAutomaticAlias(m)&&(string.IsNullOrEmpty(sourceFileId)||(m.SourceFileIds.Contains(sourceFileId)||(m.IdentityFileIds?.Contains(sourceFileId)??false)))&&AreStrongPersonAliases(m.OriginalValue,value)).Select(m=>m.Token).Distinct().ToList();
   return matches.Count==1?matches[0]:null;
  }
  private static bool AreStrongPersonAliases(string left,string right) => PersonIdentity.AreAliases(left,right);
  public static string Normalize(string value)=>string.Join(" ",value.Trim().Split((char[])null!,StringSplitOptions.RemoveEmptyEntries)).ToUpperInvariant();
 }
 public sealed class Candidate { public bool RequiresContextReview {get;set;} public string Value {get;set;}=""; public string Category {get;set;}=""; public double Confidence {get;set;}=0.7; public string Source {get;set;}="Rules"; public List<string> DetectionSources {get;set;}=new List<string>(); public string Explanation {get;set;}="Built-in deterministic recognizer"; }
}
